Here is a function in JavaScript that checks if any of the numbers in an array is a valid prime number:

function checkPrime(numbers) {
    for (let number of numbers) {
        let isPrime = true;
        for (let i = 2; i < number; i++) {
            if (number % i === 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            console.log(number + " is a prime number");
        }
    }
}

// Example usage:
let numbers = [1, 3, 5, 7, 11];
checkPrime(numbers);
// Output: 3 is a prime number
//         5 is a prime number
//         7 is a prime number
//         11 is a prime numberassistant

